class Solution {
    public int goodNodes(TreeNode root) {
        List<TreeNode> all = new ArrayList<>();
        Map<TreeNode, TreeNode> parent = new HashMap<>();
        collect(root, null, all, parent);
        int good = 0;
        for (TreeNode node : all) {
            boolean isGood = true;
            TreeNode cur = parent.get(node);
            while (cur != null) {
                if (cur.val > node.val) {
                    isGood = false;
                    break;
