            for i in range(size):
                node, idx = q.popleft()
                cur = idx - offset
                if i == 0: first = cur
                if i == size - 1: last = cur
                if node.left: q.append((node.left, 2 * cur + 1))
                if node.right: q.append((node.right, 2 * cur + 2))
            max_width = max(max_width, last - first + 1)
        return max_width

