        if not root:
            return 0
        def left_h(node):
            h = 0
            while node:
                h += 1
                node = node.left
            return h
        def right_h(node):
            h = 0
            while node:
                h += 1
                node = node.right
            return h
        lh = left_h(root)
        rh = right_h(root)
        if lh == rh:
            return (1 << lh) - 1
        return 1 + self.countNodes(root.left) + self.countNodes(root.right)

